# New profiles from Cutter's Tufts sketch (1910, vol. II, pp. 1198-1200), corroborated with NEHGR 51 (1897),
# Wyman (1879), Brooks (1855), Medford VRs (1907) and the Mass. Charitable Mechanic Assoc. Annals (1892). Added 2026-11-04.
NEH = "Larkin T. Tufts and Edward C. Booth, &ldquo;Tufts Genealogy&mdash;Earlier Generations,&rdquo; <em>New England Historical and Genealogical Register</em>, vol. 51 (July 1897)"
NE = lambda pg: f'{NEH}, p. {pg}. <a href="https://archive.org/details/newenglandhistor51wate/page/{pg}/mode/1up">Page (Internet Archive)</a>'
WY = lambda pg: f'{WYMAN}, p. {pg}. <a href="https://archive.org/details/genealogiesestat02wyma/page/{pg}/mode/1up">Page (Internet Archive)</a>'
MVRT = "<em>Vital Records of Medford, Massachusetts, to the Year 1850</em> (1907)"
MV = lambda pg: f'{MVRT}, p. {pg}. <a href="https://archive.org/details/vitalrecordsofme00medf_1/page/{pg}/mode/1up">Page (Internet Archive)</a>'
BR5 = lambda pg: f'{B55}, p. {pg}. <a href="{SCAN}{pg}">Page scan</a>'
MCMA = 'Joseph T. Buckingham, <em>Annals of the Massachusetts Charitable Mechanic Association</em> (1853), p. 67. <a href="https://archive.org/details/annalsofmassachu00buck/page/67/mode/1up">Page (Internet Archive)</a>'
OCR = '<span class="note">(Scanned text; obvious scanning errors corrected.)</span>'
PROFILES += [
 dict(slug="peter-tufts-1648", name="Capt. Peter Tufts (c. 1648&ndash;1721)", dates="c. 1648&ndash;1721", town="Malden and Medford, Mass.", born="1648", died="1721", era="Colonial", line="Son of Peter Tufts the immigrant",
  bio='<p>The eldest son of ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + ' carried the family name across the Mystic into Medford. Brooks calls him &ldquo;Peter Tufts, of Medford, commonly called Capt. Peter.&rdquo; In 1680 his father deeded him half of the 350-acre Medford farm bought from Richard Russell&rsquo;s executor (Wyman, p. 957), and the land the immigrant had bought of Mrs. Nowell later &ldquo;descended to his son, Capt. Peter Tufts&rdquo; (Brooks, p. 543).</p>'
   + Q("Peter, of Medford, who lived upon a portion of the three hundred and fifty acres of the original Cradock farm, which his father had bought of Richard Russell's estate in 1677.", CR(215, ", note"))
   + Q("Peter2 (Peter1), (Capt.), Medford; commissioned lieutenant of cavalry-troop 17 October, 1699", NE(300), note=OCR)
   + '<p>He was married three times and had seventeen children, most of whom died young. Among the sons who lived were the Rev. Thomas Tufts (Harvard 1701), the Rev. John Tufts of Newbury (Harvard 1708), author of the first American instruction book for singing by note, and ' + PL("simon-tufts-1700", "Dr. Simon Tufts (1700&ndash;1747)") + ', Medford&rsquo;s first physician (NEHGR 51, pp. 302&ndash;303).</p>'
   + '<p>His will, dated July 24, 1719, and proved October 2, 1721, left his son Peter the house in Malden; his sons Thomas and John shares of six hundred acres &ldquo;between Quaboag (Brookfield) and Springfield&rdquo;; his son Simon woodland at Spot Pond; and legacies to his daughters, among them the unmarried ' + PL("sarah-tufts-hinckley", "Sarah") + ' (Wyman, p. 958).</p>'
   + Q("TUFTS, Peter, Capt., Sept. 19, 1721. [Sept. 20, a. 73, G.R.1.]", MV(445)),
  service='<p>Lieutenant of a troop of horse, commissioned October 17, 1699 (NEHGR 51, p. 300). The rank of captain by which Brooks and the town records know him is not dated in the sources checked.</p>',
  family='<p>Father: ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + '. Mother: Mary (Pierce). Brother: James Tufts, killed at Bloody Brook (' + PL("james-tufts-1675", "profile") + '). Children by Elizabeth Lynde: Elizabeth (Mrs. Jacob Hurd), Anna (Mrs. John Brocas), Peter, Mary (Mrs. James Austin) and the Rev. Thomas. By Mercy Cotton: the Rev. John, Mercy (Mrs. John Bradshaw), ' + PL("simon-tufts-1700", "Dr. Simon") + ', ' + PL("sarah-tufts-hinckley", "Sarah (Mrs. Job Hinckley)") + ', Dorothy (Mrs. Tristram Coffin) and Lydia, with eight who died in infancy (NEHGR 51, pp. 300&ndash;301; Wyman, p. 958).</p>'
   + Q("Peter, born about 1648.", CUT(2, 1198), note="Cutter names him only in the list of the immigrant&rsquo;s children."),
  unverified="<strong>Birth:</strong> no birth record has been found; &ldquo;about 1648&rdquo; (NEHGR, Cutter) and 1648 (Brooks) agree with &ldquo;a. 73&rdquo; at death. The exact date 5 May 1648 seen in online trees has no source here. <strong>Death date:</strong> the Medford record says Sept. 19, 1721; the gravestone, NEHGR and Wyman say Sept. 20. <strong>First wife&rsquo;s death:</strong> NEHGR gives 15 June 1684; Wyman and Brooks give July 15, 1684. <strong>Second wife&rsquo;s name:</strong> Brooks prints &ldquo;Mary Cotton&rdquo; but then calls her Mercy; NEHGR and Wyman have Mercy. <strong>Third wife:</strong> NEHGR calls her Prudence, widow of William Wyman; online trees give &ldquo;Prudence Putnam,&rdquo; which is not in the sources checked."),
 dict(slug="james-tufts-1675", name="James Tufts (c. 1650&ndash;1675)", dates="c. 1650&ndash;1675", town="Charlestown and Deerfield, Mass.", born="1650", died="1675", era="Colonial", line="Son of Peter Tufts the immigrant",
  bio='<p>James Tufts, a younger son of ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + ', is the first of the family known to have died in war. In King Philip&rsquo;s War he was a teamster with Capt. Thomas Lathrop&rsquo;s company, which was ambushed while escorting carts of grain from Deerfield on September 18, 1675, at the stream afterward called Bloody Brook.</p>'
   + Q("James2 (Peter1), resident of Deerfield; was with Capt. Lothrop as teamster when the latter was ambuscaded at Bloody Brook, and was there killed, 18 September, 1675.", NE(301))
   + Q("James, son of Peter Tufts, was born in Charlestown, about 1650. He was a soldier in King Philip's war, and was killed in the battle of Bloody Brook, September 18, 1675.", CUT(2, 1198), note=OCR)
   + Q("James 7. Son of Peter 1; soldier at Bloody Brook, and there was slain Sept. 18. 1675.", WY(959))
   + '<p>He left one child, ' + PL("james-tufts-1672", "James Tufts (1672&ndash;1733)") + ', whom the immigrant remembered in his will with &ldquo;new house near Mystic bridge; 40 acres near house&rdquo; (Wyman, p. 958). Through that grandson the line runs to ' + PL("william-tufts-13-6", "Lieut. William Tufts") + ' of Medford.</p>',
  service="<p>King Philip&rsquo;s War: teamster with Capt. Lathrop&rsquo;s company; killed at Bloody Brook (South Deerfield), September 18, 1675 (NEHGR 51, p. 301; Wyman, p. 959).</p>",
  family='<p>Father: ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + '. Brother: ' + PL("peter-tufts-1648", "Capt. Peter Tufts") + '. Son: ' + PL("james-tufts-1672", "James Tufts (1672&ndash;1733)") + ', by Elizabeth Wells (see Spouse).</p>',
  unverified="<strong>Birth:</strong> &ldquo;about 1650&rdquo; is Cutter&rsquo;s estimate; no record found. <strong>Brooks&rsquo;s confusion:</strong> Brooks (1855, p. 550) says a James &ldquo;said (B) to have been a son of Peter (No. 1)&rdquo; married Mary Dill in 1729 and was &ldquo;supposed to have been killed by the Indians.&rdquo; The Dill marriage belongs to his son (NEHGR, Wyman), so Brooks has run father and son together."),
 dict(slug="james-tufts-1672", name="James Tufts (1672&ndash;1733)", dates="1672&ndash;1733", town="Salem, Charlestown and Medford, Mass.", born="1672", died="1733", era="Colonial", line="Grandson of Peter Tufts the immigrant",
  bio='<p>The only child of ' + PL("james-tufts-1675", "James Tufts") + ', who was killed at Bloody Brook when the boy was about three, James was provided for by his grandfather, ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + '. He lived for a time at Salem and in Boston before settling on the family land at Medford.</p>'
   + Q("James (2), only child of James (1) Tufts, was born in 1672, in Charlestown, and died at Medford, July 19, 1733. His gravestone is standing in the Medford burial ground. He lived at Salem, removing with his family May 12, 1704, to Charlestown.", CUT(2, 1198), note=OCR)
   + Q("Medford; received by grandfather's will new house near Mystic Bridge, with forty acres, etc.", NE(303))
   + '<p>His later years were troubled. In 1721, the year smallpox killed his wife Ruth, he gave his son James power of attorney, &ldquo;feeling incapable to act by reason of troubles,&rdquo; and deeded him fourteen acres at Walnut-tree Hill (Wyman, p. 959; Cutter, p. 1198). His inventory came to &pound;1,279.</p>'
   + Q("James, July 19, 1733, in 59th y. G.R.1.", MV(443)),
  service="<p>No military service found.</p>",
  family='<p>Father: ' + PL("james-tufts-1675", "James Tufts (killed 1675)") + '. Grandfather: ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + '. Children by Ruth: John; James (b. Jan. 16, 1703), a brick-maker; Jonathan; Ebenezer; Ruth; Elizabeth (Mrs. Jonathan Hall); ' + PL("william-tufts-13-6", "William (b. June 10, 1713)") + '; the twins Susanna and Mary; Sarah; and Grimes (NEHGR 51, pp. 303&ndash;304; Wyman, p. 959).</p>',
  unverified="<strong>Birth year:</strong> Cutter gives 1672, and Wyman quotes a Charlestown selectmen&rsquo;s entry of June 27, 1672, about the &ldquo;Child of James Tufts and Elizabeth Wells.&rdquo; But his gravestone (&ldquo;in 59th y.&rdquo;) points to 1674&ndash;75. <strong>Wife Ruth&rsquo;s surname</strong> is not given in NEHGR, Wyman or Cutter; the name Grimes found in online trees is unproven here. Wyman notes that the smallpox items for 1721 &ldquo;may as well apply to the other James.&rdquo; <strong>Lineage of William:</strong> Brooks (p. 550) makes William Tufts (b. 1713) a son of Capt. Peter; NEHGR, Wyman and Cutter all make him a son of this James. The site follows the latter."),
 dict(slug="peter-tufts-1697", name="Peter Tufts (1697&ndash;1776)", dates="1697&ndash;1776", town="Charlestown (Milk Row, now Somerville), Mass.", born="1697", died="1776", era="Colonial", line="Father of Peter Tufts of Winter Hill",
  bio='<p>Peter Tufts, a housewright, was the &ldquo;Peter of Milk Row&rdquo; from whom the Somerville Tufts farms descended. A grandson of ' + PL("peter-tufts-1617", "the immigrant") + ' through his son John of Malden, he farmed in Charlestown west of the Neck, the district now Somerville, and settled farms on his sons Peter, Timothy and Samuel.</p>'
   + Q("Peter, b. in Charlestown, 10 May, 1697.", NE(301), note="(Among the children of John Tufts of Charlestown and Malden and Mary Putnam.)")
   + Q("PETER 36. Son of John 28; housewright; m. LYDIA BUCKNAM, who d. Oct. 31, 1776, in 72d yr., g. s.; d. Dec. 5, 1776, in 80th yr., g. s.", WY(964))
   + '<p>He was taxed in Charlestown from 1727 and bought twenty-two acres of Jonathan Dowse in 1729 (Wyman, pp. 964&ndash;965). His will, dated August 9, 1774, with a codicil of April 26, 1776, and proved August 18, 1777, left his son Peter fifty-five acres bought of E. Cheever, his son Samuel the forty acres &ldquo;given me by father,&rdquo; and lots in Cambridge and Medford to ' + PL("timothy-tufts", "Timothy") + ', who was executor (Wyman, p. 965).</p>'
   + Q("Timothy, the third son of Peter of Milk Row, who was born in 1735, received from his father a farm on Elm street, at the corner of Willow avenue.", BTH(25))
   + '<p>He and Lydia lived through the first year of the Revolution on the edge of the siege lines and died within five weeks of each other in the autumn of 1776.</p>',
  service="<p>No military service found. The WikiTree story that he fought at Lexington aged 78 is not supported (see Unverified).</p>",
  family='<p>Father: John Tufts (c. 1665&ndash;1728) of Charlestown and Malden. Mother: Mary Putnam, daughter of Lieut. Nathaniel Putnam of Salem Village (NEHGR 51, p. 301). Grandfather: ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + '.</p><p>Children: Nathan (b. May 14, 1724; m. Mary Adams); <a href="{P}generations/colonial.html#peter-1728">Peter of Winter Hill</a> (b. April 24, 1728; m. Anne Adams); Lydia (b. June 5, 1731); ' + PL("timothy-tufts", "Timothy") + ' (b. Jan. 20, 1734); Samuel (b. Nov. 24, 1737; m. Martha Adams); Aaron (b. Dec. 16, 1739; m. Mary Stone); and Susanna (1742&ndash;1746) (NEHGR 51, pp. 304&ndash;305; Wyman, p. 964). Grandson: ' + PL("peter-tufts-jr", "Peter Tufts Jr. (1753&ndash;1832)") + ', son of Peter of Winter Hill.</p>',
  unverified="WikiTree (Tufts-199) says he lived on Winter Hill, that Paul Revere knocked at his door on April 18, 1775, and that he fought at Lexington aged 78. No printed source checked supports this. Booth and NEHGR place the Winter Hill farm with his son Peter (b. 1728), and the father was 77 in April 1775. The story appears to conflate father and son. Timothy&rsquo;s birth year is 1734 in NEHGR and Wyman but 1735 in Booth."),
 dict(slug="lucy-tufts-pritchard", name="Lucy Tufts Pritchard (b. 1754)", dates="b. 1754", town="Medford, Mass.", born="1754", died="", era="The Revolution", line="Daughter of Lieut. William Tufts",
  bio='<p>Lucy Tufts was the second child of ' + PL("william-tufts-13-6", "William Tufts") + ' by his second wife, Mary Francis. She grew up in Medford among a large family of half-brothers and brothers, several of whom served in the Revolution, and married two months before the fighting began at Lexington and Concord.</p>'
   + Q("Lucy, d. William and Mary, Apr. 21, 1754.", MV(150))
   + Q("Prichard (see Pritchard), Thomas and Lucy Tufts 2d, Feb. 22, 1775.", MV(279), note="(&ldquo;2d&rdquo; distinguishes her from another Lucy Tufts of the town.)")
   + Q("Lucy, born April 21, 1754; married Thomas Pritchard.", CUT(2, 1199))
   + '<p>Her husband is &ldquo;Capt. Thom[a]s&rdquo; in the record of their daughter Attalanta&rsquo;s birth, June 4, 1787 (Medford VRs, p. 114). Attalanta married Zebina Bailey on November 13, 1816 (p. 279).</p>',
  service="<p>Not applicable.</p>",
  family='<p>Father: ' + PL("william-tufts-13-6", "Lieut. William Tufts") + '. Mother: Mary Francis. Brothers and half-brothers: ' + PL("william-tufts-40-2", "William") + ', ' + PL("george-tufts-40-7", "George") + ', ' + PL("grimes-tufts-40-8", "Grimes") + ', ' + PL("samuel-tufts-41-2", "Samuel") + ', ' + PL("david-tufts-41-7", "David") + ', ' + PL("richard-tufts", "Richard") + ' and ' + PL("moses-tufts-40-6", "Moses") + '. Brooks (p. 550) lists her as no. 262, &ldquo;Lucy, b. Apr. 21, 1754; m. Thomas Pritchard.&rdquo;</p>',
  unverified="Her death date and burial have not been found. Which Thomas Pritchard she married, and his militia service as &ldquo;Capt.,&rdquo; are not established."),
 dict(slug="richard-tufts", name="Richard Tufts (b. 1763 or 1765)", dates="b. 1763 or 1765", town="Medford, Mass.", born="1765", died="", era="The Revolution", line="Son of Lieut. William Tufts",
  bio='<p>Richard Tufts was one of the younger sons of ' + PL("william-tufts-13-6", "Lieut. William Tufts") + ' and Mary Francis of Medford. The sources disagree on when he was born, and nothing more is yet known of his life.</p>'
   + Q("Richard, s. William and Mary, Nov. &mdash;, 1765. [Tuffts, bp. Nov. 3, C.R.1.]", MV(152))
   + Q("Richard, born November 17, 1763.", CUT(2, 1199))
   + '<p>Brooks agrees with the town record: &ldquo;266 Richard, b. Nov., 1765&rdquo; (p. 551).</p>',
  service="<p>Note: Pending further work. No service record has been matched to him.</p>",
  family='<p>Father: ' + PL("william-tufts-13-6", "Lieut. William Tufts") + '. Mother: Mary Francis. Sister: ' + PL("lucy-tufts-pritchard", "Lucy Tufts Pritchard") + '. Brothers and half-brothers: ' + PL("samuel-tufts-41-2", "Samuel") + ', ' + PL("david-tufts-41-7", "David") + ', ' + PL("william-tufts-40-2", "William") + ', ' + PL("george-tufts-40-7", "George") + ' and ' + PL("grimes-tufts-40-8", "Grimes") + '.</p>',
  unverified="<strong>Birth date:</strong> Cutter gives November 17, 1763. The Medford town record and Brooks give November 1765, with baptism on November 3. Brooks and this site give June 17, 1763, for his brother David, so Cutter may have confused the two. The 1765 date is preferred. His marriage, death and burial have not been found."),
 dict(slug="uriah-tufts-1768", name="Uriah Tufts (1768&ndash;1837)", dates="1768&ndash;1837", town="Medford, Boston and Charlestown, Mass.", born="1768", died="1837", era="19th Century", line="Son of William Tufts Jr. (1736&ndash;1782)",
  bio='<p>Uriah Tufts, born in Medford, became a Boston blacksmith whose family remembered him as a smith on the frigate <em>Constitution</em>.</p>'
   + Q("Uriah, s. Will[ia]m 4th and Susanah, Jan. 29, 1768.", MV(153))
   + Q("He was a blacksmith by trade, and for many years had a smithy on Constitution Wharf, Boston. He forged and drove the first bolts that were used in the construction of the famous frigate &ldquo;Constitution.&rdquo;", CUT(2, 1199), note=OCR)
   + '<p>In 1800 he was admitted to the Massachusetts Charitable Mechanic Association, the society of Boston master craftsmen founded in 1795:</p>'
   + Q("Uriah Tufts, Blacksmith.", MCMA + ", in the list of those admitted to membership in 1800")
   + Q("A pitcher which he wrought in 1800 is owned by his granddaughter. It bears a significant coat-of-arms, and the motto: &ldquo;By hammer and hand, all arts do stand.&rdquo;", CUT(2, 1199), note=OCR)
   + '<p>Cutter records that he died in Charlestown on October 22, 1837, and was buried in Malden.</p>',
  service="<p>Civil: member of the Massachusetts Charitable Mechanic Association from 1800 (Buckingham, p. 67). No military service found.</p>",
  family='<p>Father: ' + PL("william-tufts-40-2", "William Tufts Jr. (1736&ndash;1782)") + ', &ldquo;William 4th&rdquo; in the Medford records. Mother: Susannah. Brother: ' + PL("nathan-tufts-jr", "Nathan Tufts Jr.") + '. Grandfather: ' + PL("william-tufts-13-6", "Lieut. William Tufts") + '.</p><p>Children by Sarah Harris: Sarah; Elizabeth Lewis (b. March 10, 1792); William; and ' + PL("uriah-tufts-1796", "Uriah (1796&ndash;1860)") + '. By Mary Phillips: Mary (b. 1798), who married in Malden on January 29, 1818, her cousin William Tufts of Milton (Cutter, p. 1199).</p>',
  unverified="<strong>The <em>Constitution</em> bolts:</strong> Cutter is the only source found for this family claim; the frigate&rsquo;s building records have not been checked. <strong>Burial:</strong> no gravestone or Find a Grave memorial found. <strong>Uncle of the same name:</strong> Brooks (p. 550) and Cutter (p. 1199) list an older Uriah, son of Lieut. William Tufts and Catherine Wyman; he is a different man."),
 dict(slug="uriah-tufts-1796", name="Uriah Tufts (1796&ndash;1860)", dates="1796&ndash;1860", town="Boston and Charlestown, Mass.", born="1796", died="1860", era="19th Century", line="Son of Uriah Tufts (1768&ndash;1837)",
  bio='<p>The son of the blacksmith ' + PL("uriah-tufts-1768", "Uriah Tufts") + ', he chose the finer trade of cabinetmaking and kept a shop in Boston for many years while living across the river in Charlestown.</p>'
   + Q("Uriah (2), son of Uriah (1) Tufts, was born in Boston, November 13, 1796, and died August 14, 1860. He was educated in the district schools, learned the trade of cabinet maker, and for many years was in business in Boston, residing in Charlestown.", CUT(2, 1199), note=OCR)
   + '<p>His first wife, Deborah Weston Thomas, died in 1829, leaving young children; of their five, only ' + PL("william-tufts-1820", "William (1820&ndash;1893)") + ' is known to have lived to adulthood. William was put to work at nine, the year his mother died (Cutter, pp. 1199&ndash;1200).</p>',
  service="<p>No military service found.</p>",
  family='<p>Father: ' + PL("uriah-tufts-1768", "Uriah Tufts (1768&ndash;1837)") + '. Mother: Sarah Harris. Children by Deborah W. Thomas: Uriah Jr. (1818&ndash;1819); ' + PL("william-tufts-1820", "William (1820&ndash;1893)") + '; Mary W. (1823&ndash;1830); Uriah (born January 1826, died young); and Edwin R. (b. February 12, 1829). By Mary W. Carlisle: Helen M. (b. January 1, 1844), who married Dr. Harry L. Jewell of Bangor, Maine (Cutter, p. 1199).</p>',
  unverified="Cutter is the only source found for his life, both marriages and his children. Cutter&rsquo;s statement that Deborah Thomas was a direct descendant of Gen. John Thomas of the Dorchester Heights fortification is not checked. Edwin R.&rsquo;s death year reads 1829 in the scanned text and is uncertain. No Boston directory, death record or gravestone has yet been checked."),
 dict(slug="william-tufts-1820", name="William Tufts (1820&ndash;1893)", dates="1820&ndash;1893", town="Boston, Mass.", born="1820", died="1893", era="19th Century", line="Son of Uriah Tufts (1796&ndash;1860)",
  bio='<p>William Tufts went to work at nine and rose from apprentice to one of Boston&rsquo;s prosperous confectioners and caterers.</p>'
   + Q("He attended the public schools, but when he was nine years old was set to work to earn his own living. He was apprenticed to George Vinton, a prominent confectioner of Boston, and learned the business thoroughly.", CUT(2, 1199), note=OCR)
   + Q("He then embarked in the confectionery business on his own account, on Washington street, Boston, and to his confectionery trade added catering.", CUT(2, 1199) + " (continued on p. 1200)", note=OCR)
   + '<p>Before going into business for himself he was foreman for Charles C. Copeland, a leading confectionery manufacturer. In 1876 he settled on Dwight Street in Boston&rsquo;s South End, where he lived until his death on April 3, 1893. He was a Freemason of Lebanon Lodge and an Odd Fellow of Salome Lodge. Cutter adds that he later lost his sight but stayed active in business (Cutter, p. 1200).</p>'
   + Q("His religion was to &ldquo;do unto others as you would have them do unto you.&rdquo;", CUT(2, 1200), note=OCR),
  service="<p>No military service found.</p>",
  family='<p>Father: ' + PL("uriah-tufts-1796", "Uriah Tufts (1796&ndash;1860)") + '. Mother: Deborah Weston Thomas. Grandfather: ' + PL("uriah-tufts-1768", "Uriah Tufts (1768&ndash;1837)") + '.</p><p>Children by Mary Curtis Anthony: May Weston (b. 1843?); George Curtis (died in infancy, 1847); Esther O. (b. 1850). By Eunice Weston: Maria Faxon (b. 1857; m. Oscar G. Rankin); Jeannette Webster (m. John L. Flanigan); and William Phillips (died 1866). Maria&rsquo;s son William Tufts Rankin (b. 1883) was adopted by his grandfather and renamed William Tufts Jr. (Cutter, p. 1200).</p>',
  unverified="Cutter is the only source found for his career and family. A Massachusetts death index lists a William Tufts who died in Boston in 1893 (vol. 438), but it has not been opened or matched to him. Some dates in the scanned text are unclear, including the year he lost his sight and May Weston&rsquo;s birth year. Boston directories and his Washington Street address have not yet been checked."),
 dict(slug="sarah-tufts-hinckley", name="Sarah Tufts Hinckley (1702&ndash;1784)", dates="1702&ndash;1784", town="Medford and Brookfield, Mass.", born="1702", died="1784", era="Colonial", line="Daughter of Capt. Peter Tufts",
  bio='<p>Sarah Tufts was a daughter of ' + PL("peter-tufts-1648", "Capt. Peter Tufts") + ' of Medford by his second wife, Mercy Cotton. Through her mother she was a great-granddaughter of Gov. Simon Bradstreet and the poet Anne Bradstreet (Brooks, p. 544). She was still single when her father made his will in 1719, which named &ldquo;daus. &hellip; Sarah Tufts&rdquo; among his legatees and left her brothers land at Quaboag, the later Brookfield (Wyman, p. 958). She married a Brookfield man and spent the rest of her long life there.</p>'
   + Q("Sarah, b. 13 May, 1702; m. 9 Dec., 1723, Job, son of Samuel and Sarah (Pope) Hinckley, who was b. 16 Feb., 1687-8, at Brookfield, and there d. 4 July, 1753. She d. 4 Sept., 1784.", NE(301), note=OCR),
  service="<p>Not applicable.</p>",
  family='<p>Father: ' + PL("peter-tufts-1648", "Capt. Peter Tufts") + '. Mother: Mercy Cotton. Brother: ' + PL("simon-tufts-1700", "Dr. Simon Tufts (1700&ndash;1747)") + '. Grandfather: ' + PL("peter-tufts-1617", "Peter Tufts the immigrant") + '. Wyman (p. 958) lists her as &ldquo;xv. Sarah, m. Job Hinkley.&rdquo;</p>',
  unverified="Her children and burial place are not yet found. Brookfield vital records have not been checked."),
]
SP.update({
 "peter-tufts-1648": "<ul><li><strong>Elizabeth Lynde</strong>, daughter of Ensign Thomas and Elizabeth Lynde of Malden. Married August 26, 1670. She died in 1684 &ldquo;in 33d year&rdquo; and is buried at Malden (NEHGR 51, p. 300; Wyman, p. 958).</li><li><strong>Mercy Cotton</strong> (1666&ndash;1715), daughter of the Rev. Seaborn and Dorothy (Bradstreet) Cotton. Married December 16, 1684. Died June 18, 1715; gravestone at Medford (NEHGR 51, p. 300).</li><li><strong>Prudence (&mdash;) Wyman</strong>, widow of William Wyman. Marriage agreement June 11, 1717. She was living in 1745, when she testified in court as a midwife (Wyman, p. 958).</li></ul>",
 "james-tufts-1675": "<ul><li><strong>Elizabeth Wells.</strong> Cutter (p. 1198) says he &ldquo;married Elizabeth Wells.&rdquo; Wyman (p. 959) records only a court case with her about 1669 and a Charlestown selectmen&rsquo;s order of June 27, 1672, for the &ldquo;Child of James Tufts and Elizabeth Wells, to be kept by Susanna White.&rdquo; No marriage record has been found.</li></ul>",
 "james-tufts-1672": "<ul><li><strong>Ruth</strong> (surname not given). Admitted to the Cambridge church November 4, 1705; died November 26, 1721, &ldquo;in her 40th year&rdquo; (NEHGR 51, p. 303).</li><li><strong>Dinah Morse</strong>, probably daughter of John and Dinah (Knight) Morse of Woburn. Married at Woburn, June 16, 1725.</li><li><strong>Mary (Cheney) Dill.</strong> Married September 4, 1729 (NEHGR 51, p. 303; Wyman, p. 959).</li></ul>",
 "peter-tufts-1697": "<ul><li><strong>Lydia Bucknam</strong>, daughter of Joses and Judith (Worth) Bucknam of Malden. Born 170&ndash;; died October 31, 1776, &ldquo;in 72d yr.&rdquo; (NEHGR 51, p. 304; Wyman, p. 964). Marriage date and place: Note: Pending further work. WikiTree gives August 1723, Malden, which is not in the printed sources checked.</li></ul>",
 "lucy-tufts-pritchard": "<ul><li><strong>Thomas Pritchard</strong> (also Prichard). Married at Medford, February 22, 1775 (Medford VRs, p. 279). Called &ldquo;Capt. Thomas&rdquo; in 1787 (p. 114).</li></ul>",
 "richard-tufts": "<p>Note: Pending further work.</p>",
 "uriah-tufts-1768": "<ul><li><strong>Sarah Harris</strong>, born in Watertown May 16, 1764. Married July 8, 1789. Died September 11, 1797.</li><li><strong>Mary Phillips</strong>, born in Malden. Married November 30, 1797. Died in Charlestown, September 15, 1853 (Cutter, p. 1199).</li></ul>",
 "uriah-tufts-1796": "<ul><li><strong>Deborah Weston Thomas</strong> (October 14, 1798 &ndash; February 20, 1829).</li><li><strong>Mary W. Carlisle.</strong> Married June 1830 (Cutter, p. 1199).</li></ul>",
 "william-tufts-1820": "<ul><li><strong>Mary Curtis Anthony</strong> of Marblehead. Married November 1841. Died December 14, 1855.</li><li><strong>Eunice Weston</strong>, born at Warren, Maine, in 1824, daughter of Edward and Margaret (Harriman) Weston. Married in Boston, January 1857. Died at her home in Boston, August 3, 1907 (Cutter, p. 1200).</li></ul>",
 "sarah-tufts-hinckley": "<ul><li><strong>Job Hinckley</strong> (1688&ndash;1753), son of Samuel and Sarah (Pope) Hinckley, born at Brookfield February 16, 1687/8. Married December 9, 1723; died at Brookfield July 4, 1753 (NEHGR 51, p. 301).</li></ul>",
})
